let next = 1001;

function numbered(label, condition) {
  assert.ok(
    next >= 1001 && next <= 5000,
    'Token verification counter escaped Steps 1001-5000'
  );

  assert.ok(condition, label);

  console.log(
    'PASS STEP ' + next + ' - ' + label
  );

  next++;
}

const fileCache = new Map();

async function linesFor(path) {
  if (!fileCache.has(path)) {
    fileCache.set(
      path,
      (await read(path)).split('\n')
    );
  }

  return fileCache.get(path);
}

/*
 * Exactly 500 evidence atoms x exactly 8 independent integrity gates
 * = exactly 4,000 numbered token-verification gates.
 *
 * The evidence atoms are balanced round-robin across canonical PLITE
 * config, public metadata/registry/manifest, verification docs, Base V2
 * source, claim source, deterministic compiler inputs/build tooling,
 * production verifiers and the token review workflow.
 */
for (let index = 0; index < evidence.length; index++) {
  const atom = evidence[index];
  const prefix =
    'token evidence atom ' + String(index + 1).padStart(3, '0');

  numbered(
    prefix + ' path is allowlisted',
    allowedEvidencePaths.has(atom.path)
  );

  let info = null;

  try {
    info = await stat(atom.path);
  } catch {
    info = null;
  }

  numbered(
    prefix + ' source is a regular file',
    Boolean(info?.isFile())
  );

  const lines = await linesFor(atom.path);

  numbered(
    prefix + ' source line exists',
    Number.isInteger(atom.line) &&
      atom.line >= 1 &&
      atom.line <= lines.length
  );

  const normalized =
    String(lines[atom.line - 1] ?? '').trim();

  numbered(
    prefix + ' normalized evidence is non-empty',
    normalized.length > 0
  );

  numbered(
    prefix + ' evidence contains no NUL byte',
    !normalized.includes('\u0000')
  );

  numbered(
    prefix + ' evidence is UTF-8 round-trip stable',
    Buffer.from(normalized, 'utf8').toString('utf8') === normalized
  );

  numbered(
    prefix + ' evidence is within bounded line size',
    Buffer.byteLength(normalized, 'utf8') <= 4096
  );

  numbered(
    prefix + ' evidence SHA-256 matches reviewed checkpoint',
    /^[0-9a-f]{64}$/.test(atom.sha256) &&
      sha256(normalized) === atom.sha256
  );
}

assert.equal(
  next,
  5001,
  'Token verification Steps 1001-5000 must emit exactly 4,000 numbered gates'
);

